import type { ColorTokens } from "@/registry/types/pdf-themes";

/** Theme color token keys that can be used for the color prop */
export const THEME_COLOR_KEYS = [
  "foreground",
  "background",
  "muted",
  "mutedForeground",
  "primary",
  "primaryForeground",
  "border",
  "accent",
  "destructive",
  "success",
  "warning",
  "info",
] as const satisfies (keyof ColorTokens)[];

/** Resolves a color value: theme token key → hex, or raw CSS color as-is. */
export const resolveColor = (value: string, colors: ColorTokens): string => {
  const key = value as (typeof THEME_COLOR_KEYS)[number];
  return THEME_COLOR_KEYS.includes(key) ? colors[key] : value;
};

import { isValidElement } from "react";
import type { DependencyList, ReactNode } from "react";

import { professionalTheme } from "@/registry/themes/professional";

export type PdfcnTheme = typeof professionalTheme;

let serializedTheme = professionalTheme;

export interface PdfcnThemeProviderProps {
  theme?: PdfcnTheme;
  children: ReactNode;
}

const renderForSerializer = (
  children: ReactNode,
  theme: PdfcnTheme
): ReactNode => {
  serializedTheme = theme;

  if (!isValidElement(children) || typeof children.type !== "function") {
    return children;
  }

  return (children.type as (props: unknown) => ReactNode)(children.props);
};

export const PdfcnThemeProvider = ({
  theme,
  children,
}: PdfcnThemeProviderProps) =>
  renderForSerializer(children, theme ?? professionalTheme);

export const usePdfcnTheme = (): PdfcnTheme => serializedTheme;

export const useSafeMemo = <T,>(factory: () => T, _deps: DependencyList): T =>
  factory();

import {
  renderToHtml,
  renderToHtmlParts,
  renderToJson,
} from "@unlayer/react-elements";
import type { ReactElement } from "react";

export interface ElementsHtmlOptions {
  title?: string;
  fonts?: { url: string }[];
}

export interface ElementsPrintOptions {
  margin?: string;
  size?: string;
}

/**
 * Render an Elements `<Document>` tree to a complete print-ready HTML
 * document (no React hydration markers). Pass the result to any HTML-to-PDF
 * library (Puppeteer, Playwright, wkhtmltopdf).
 *
 * ```ts
 * import { InvoiceDocument } from "@/components/pdf/blocks/invoice-classic/invoice-classic";
 * import { renderElementsHtml } from "@/lib/elements-html";
 *
 * const html = renderElementsHtml(<InvoiceDocument />, { title: "Invoice" });
 * ```
 */
export const renderElementsHtml = (
  element: ReactElement,
  options?: ElementsHtmlOptions
): string => renderToHtml(element, options);

/**
 * Render to `{ head, body, css, js, tags }` parts for custom document shells
 * (existing page templates, ESP templates, iframe `srcdoc`, CSS inlining).
 */
export const renderElementsHtmlParts = (element: ReactElement) =>
  renderToHtmlParts(element);

/**
 * Export design JSON for visual-editor round-tripping (Unlayer builder).
 */
export const renderElementsJson = (element: ReactElement) =>
  renderToJson(element);

/**
 * Print CSS helpers for PDF output: `@page` margins/size, page-break
 * utilities, and header/footer positioning. Inject into the HTML shell or
 * your converter's `print` options.
 */
export const getElementsPrintCss = (options?: ElementsPrintOptions): string => {
  const margin = options?.margin ?? "12mm 14mm";
  const size = options?.size ?? "A4 portrait";
  return [
    `@page { size: ${size}; margin: ${margin}; }`,
    ".pdfcn-page-break { break-before: page; }",
    ".pdfcn-avoid-break { break-inside: avoid; }",
    ".pdfcn-doc-header { position: running(header); }",
    ".pdfcn-doc-footer { position: running(footer); }",
    "@media print { .pdfcn-no-print { display: none; } }",
  ].join("\n");
};

export type HtmlToPdfAdapter = (html: string) => Promise<Uint8Array>;

/**
 * Generate a PDF buffer from Elements print-ready HTML.
 *
 * Bring your own HTML-to-PDF converter (Puppeteer, Playwright, …) — pdfcn
 * intentionally does not bundle a browser engine:
 *
 * ```ts
 * import puppeteer from "puppeteer";
 * import { InvoiceDocument } from "@/components/pdf/blocks/invoice-classic/invoice-classic";
 * import { generateElementsPdf } from "@/lib/elements-generate";
 * import { renderElementsHtml } from "@/lib/elements-html";
 *
 * const browser = await puppeteer.launch();
 * const pdf = await generateElementsPdf({
 *   html: renderElementsHtml(<InvoiceDocument />),
 *   htmlToPdf: async (html) => {
 *     const page = await browser.newPage();
 *     await page.setContent(html, { waitUntil: "networkidle0" });
 *     const buffer = await page.pdf({ format: "A4", printBackground: true });
 *     await page.close();
 *     return new Uint8Array(buffer);
 *   },
 * });
 * ```
 */
export const generateElementsPdf = async ({
  html,
  htmlToPdf,
}: {
  html: string;
  htmlToPdf?: HtmlToPdfAdapter;
}): Promise<Uint8Array> => {
  if (!htmlToPdf) {
    throw new Error(
      "generateElementsPdf needs an `htmlToPdf` adapter (Puppeteer, Playwright, …). " +
        "Pass one in — see the docstring example. pdfcn does not bundle a browser engine."
    );
  }
  const pdf = await htmlToPdf(html);
  return pdf instanceof Uint8Array ? pdf : new Uint8Array(pdf);
};
